// Analog Read Serial — read potentiometer
int potPin = A0;
int val = 0;

void setup() {
  Serial.begin(9600);
}

void loop() {
  val = analogRead(potPin);
  int mv = map(val, 0, 1023, 0, 5000);
  Serial.print("ADC: ");
  Serial.print(val);
  Serial.print("  mV: ");
  Serial.println(mv);
  delay(100);
}
